def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary 
    of the letter with the most repetition and containing the corresponding count. If several 
    letters have the same occurrence, return all of them.

    Args:
        test (str): A string of space-separated lowercase letters.

    Returns:
        dict: A dictionary where keys are the letters with the most repetition and values are their counts.
    """

    # Split the input string into a list of letters
    letters = test.split()

    # If the input string is empty, return an empty dictionary
    if not letters:
        return {}

    # Initialize a dictionary to store the count of each letter
    letter_count = {}

    # Iterate over each letter in the list
    for letter in letters:
        # If the letter is already in the dictionary, increment its count
        if letter in letter_count:
            letter_count[letter] += 1
        # Otherwise, add the letter to the dictionary with a count of 1
        else:
            letter_count[letter] = 1

    # Find the maximum count in the dictionary
    max_count = max(letter_count.values())

    # Initialize an empty dictionary to store the letters with the maximum count
    max_letters = {}

    # Iterate over each letter and its count in the dictionary
    for letter, count in letter_count.items():
        # If the count is equal to the maximum count, add the letter to the max_letters dictionary
        if count == max_count:
            max_letters[letter] = count

    # Return the dictionary of letters with the maximum count
    return max_letters

# Example use cases:
print(histogram('a b c'))  # Output: {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # Output: {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # Output: {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # Output: {'b': 4}
print(histogram(''))  # Output: {}
